// Para cada sesión cerrada, extraer payload para Claude.
const out = [];
for (const row of $input.all()) {
  const props = row.json.properties || {};
  out.push({
    page_id: row.json.id,
    sesion_id: props['ID Sesion']?.title?.[0]?.plain_text || row.json.id,
    fecha_sesion: props['Fecha Sesion']?.date?.start,
    tipo_sesion: props['Tipo Sesion']?.select?.name || 'seguimiento',
    plantilla: props['Plantilla Informe']?.select?.name || 'seguimiento',
    duracion_min: props['Duracion Min']?.number || 50,
    notas_sesion: props['Notas Sesion']?.rich_text?.map(r => r.plain_text).join('') || '',
    objetivos: props['Objetivos Trabajados']?.rich_text?.map(r => r.plain_text).join('') || '',
    tareas: props['Tareas Asignadas']?.rich_text?.map(r => r.plain_text).join('') || '',
    paciente_relation_id: props.Paciente?.relation?.[0]?.id || null
  });
}
return out.map(item => ({ json: item }));

