// Parsear respuesta Claude y preparar payload para update Notion
const response = $input.item.json;
const content = response.content?.[0]?.text || '{}';

let informe;
try {
  // Claude a veces envuelve en ```json ... ```
  const cleaned = content.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
  informe = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Output Claude no parseable: ${content.substring(0, 200)}`);
}

const sesionData = $('Extraer datos sesión').item.json;

const resumenTexto = [
  `**Motivo**: ${informe.motivo || ''}`,
  ``,
  `**Contenido de la sesión**: ${informe.contenido_sesion || ''}`,
  ``,
  `**Evolución**: ${informe.evolucion || ''}`,
  ``,
  `**Plan terapéutico**: ${informe.plan_terapeutico || ''}`,
  ``,
  `**Observaciones**: ${informe.observaciones || ''}`,
  ``,
  `_Generado por IA — pendiente de revisión y aprobación por el profesional._`
].join('\n');

return {
  page_id: sesionData.page_id,
  resumen_ia: resumenTexto,
  raw_informe: informe
};

